class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        cells = m * n

        def comb(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            fact = [1] * (a + 1)
            for i in range(1, a + 1):
                fact[i] = fact[i - 1] * i % MOD

            inv_fact = [1] * (a + 1)
            inv_fact[a] = pow(fact[a], MOD - 2, MOD)
            for i in range(a, 0, -1):
                inv_fact[i - 1] = inv_fact[i] * i % MOD

            return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

        def line_distance_sum(length: int) -> int:
            return length * (length - 1) * (length + 1) // 6

        pair_sum = (
            n * n * line_distance_sum(m) +
            m * m * line_distance_sum(n)
        ) % MOD

        ways_to_choose_remaining = comb(cells - 2, k - 2)
        return pair_sum * ways_to_choose_remaining % MOD
